          "title": "法律行為・無効と取消し",
          "easyMarkdown": "**問題：次の4つのうち、民法上、正しい説明はどれか。**\n\n**選択肢1**\n\n親などから営業を許可された未成年者が、その営業に関する契約などの意思表示（契約を結ぶなど、自分の意思を外部に示すこと）をした。\n\nしかし、そのとき本人には意思能力（自分の行為の意味や結果を理解して判断する能力）がなかった。\n\nこの場合、その法律行為（契約など、法律上の効果を生じさせる行為）は無効（初めから法律上の効力がないこと）となる。\n\n---\n\n**選択肢2**\n\n公の秩序（社会の基本的なルールや利益）に反する契約でも、契約した本人同士が納得して合意（互いに承諾すること）していれば、その契約は有効となる。\n\n---\n\n**選択肢3**\n\n詐欺（だまして相手に契約させること）による意思表示は、取り消せば初めから無効だったことになる。\n\n一方、強迫（脅して相手に契約させること）による意思表示は、取り消さなくても初めから無効となる。\n\n---\n\n**選択肢4**\n\n売主が自分の所有物ではない、他人の土地について売買契約を結んだ場合、その売買契約は無効となる。\n\nただし、本当の所有者が追認（後から認めること）すれば有効となる。\n\n(正解 1) **民法3条の2**\n\n| 肢 | 判定 | なぜ？ |\n|--------|--------|--------|\n| 1 | ○ | 意思能力がなければ、営業の許可があっても無効。 |\n| 2 | × | 公序良俗（社会の基本的な道徳・秩序）に反する契約は、合意しても無効。 |\n| 3 | × | 詐欺も強迫も原則として**取り消せる**。強迫だから当然無効ではない。 |\n| 4 | × | 他人物売買でも、売買契約そのものは有効に成立する。 |\n\n**重要なのは4番。** 例えば、Aが他人Bの土地をCに売る約束をした場合、その契約自体は成立する。AにはBから所有権を取得してCに移転する義務が生じる。\n\n**暗記：他人物売買は契約自体が有効。無効と取消しは区別！**\n\n出典：令和6年度公式試験・問1。\n\n---",
