          "title": "共有の土地・所在不明者がいる場合",
          "easyMarkdown": "**問題：甲土地をA・B・C・Dの4人で共有（複数人で同じ土地の所有権を持つこと）しており、各人の共有持分（所有権の割合）は4分の1ずつである。**\n\nところが、Dの居場所が分からない。Dの持分は相続財産には含まれていない。\n\nこの状況について、**正しい説明はどれか。**\n\n### 甲土地の持分\n\nA・B・Cは所在判明、Dだけ所在不明\n\n**選択肢1**\n\n甲土地に、形状（土地の形）または効用（土地の使い道や役割）を大きく変えるような変更を加える場合、共有者の過半数の同意が必要になる。\n\nしたがって、このケースではA・B・Cの3人が同意すれば変更できる。\n\n---\n\n**選択肢2**\n\n甲土地の所有者ではないEが、誤って登記名義人（登記簿上の所有者）になっている。\n\nEに対して抹消登記（間違った登記を消す手続）を求めるには、所在が分かっているA・B・Cのうち、少なくとも2人の同意が必要となる。\n\n---\n\n**選択肢3**\n\nA・B・Cの3人が同意すれば、甲土地を資材置場として使いたいFに対して、賃貸借契約（賃料を受け取って土地を貸す契約）を結び、**3年間**貸すことができる。\n\n---\n\n**選択肢4**\n\nAが裁判所に申し立て、所在不明者Dの共有持分をAに取得させる決定が出た。\n\nこの場合、Dは決定から3年以内であれば、取得された持分の時価相当額（現在の市場価格に相当する金額）を**Aに対して自分への支払いを求める**ことができる。\n\n(正解 3) **民法251条・252条・262条の2**\n\n| 肢 | 判定 | なぜ？ |\n|--------|--------|--------|\n| 1 | × | 著しい変更には原則として**全員の同意**が必要。 |\n| 2 | × | 誤った登記の抹消を求めるのは保存行為。共有者が単独でできる。 |\n| 3 | ○ | 資材置場として土地を3年間貸すのは、設問の条件では管理行為。持分3/4で過半数を満たす。 |\n| 4 | × | Dは持分を取得したAに時価相当額の支払いを請求できる。誤りは「決定から3年以内に限る」という制限。民法262条の2第4項にはこの3年制限はない（一般の消滅時効とは別）。 |\n\n**共有物の3大ルール**\n\n| 行為 | 必要な同意 |\n|--------|--------|\n| 保存行為（壊れたものを守る・権利を保全する） | 各共有者が単独で可能 |\n| 管理行為（通常の利用方法を決める） | 持分価格の過半数 |\n| 重大な変更（大きな改造・処分など） | 原則、全員一致 |\n\n**覚え方：「保存は一人、管理は過半数、大変更は全員！」**\n\nこの問題では、短期の土地賃貸借を管理行為として決められるという点も大事。建物所有目的ではない一般的な土地賃貸借なら、一定の条件の下で5年以内の設定が管理行為として扱われる。\n\n出典：令和6年度公式試験・問3。\n\n---",
