          "title": "売買契約後に売主が死亡した場合",
          "easyMarkdown": "**問題：Aが売主、Bが買主となって甲土地の売買契約を結んだ。その直後にAが死亡し、CがAの財産と法律上の地位を単独相続（1人だけで相続）した。**\n\nこの場合について、**正しい説明はどれか。**\n\n**選択肢1**\n\nCは売買代金を受け取ったにもかかわらず、甲土地の引渡しをしない意思を明確に伝えた。\n\nこの場合でもBが契約解除（契約を解消すること）をするには、Cに対して相当期間（合理的な長さの期限）を定めた催告（約束を果たすよう要求すること）が必ず必要になる。\n\n---\n\n**選択肢2**\n\n買主Bが期限までに代金を支払わなかったとしても、売買契約の解除権（契約を解除できる権利）は亡くなったAだけに認められる一身専属権（本人だけに帰属して相続されない権利）なので、相続人Cは契約を解除できない。\n\n---\n\n**選択肢3**\n\nBがすでに代金を支払っていても、甲土地の所有権移転登記（登記簿上の所有者を変更する登記）がなければ、Aの相続人Cに土地の引渡しを請求できない。\n\n---\n\n**選択肢4**\n\n売主AがBをだまして、この土地売買契約を結ばせていた。\n\nこの場合、買主BはAの相続人Cに対して、詐欺を理由に契約の取消し（いったん生じた法律効果を取り消すこと）を主張できる。\n\n(正解 4) **民法541条・542条・896条など**\n\n| 肢 | 判定 | なぜ？ |\n|--------|--------|--------|\n| 1 | × | 明確な履行拒絶（義務を果たさないと表明すること）があれば、無催告解除できる場合がある。 |\n| 2 | × | 契約上の解除権も原則として相続人Cに引き継がれる。 |\n| 3 | × | Cは売主Aの地位を引き継いだ人。Bは原則として登記がなくてもCに契約上の引渡しを請求できる。 |\n| 4 | ○ | Aが行った詐欺について、BはAの地位を承継したCに取消しを主張できる。 |\n\nここでの最大の引っかけは3番。\n\n**「登記がないと第三者に対抗できない」ことと、「売主の相続人に契約の履行を求められるか」は違う**んだ。\n\n**暗記：相続人は原則として契約上の権利義務も引き継ぐ。**\n\n出典：令和6年度公式試験・問4。\n\n---",
