          "easyMarkdown": "**問題：次のうち、現在の民法の条文として規定されていない説明はどれか。**\n\n**選択肢1**\n\n隔地者間（離れた場所にいる者同士）の契約は、承諾（申込みを受け入れる返事）の通知を発送した時点で成立する。\n\n---\n\n**選択肢2**\n\n無効な行為に基づいて物やお金を受け取った人は、原状回復（受け取る前の状態に戻すこと）の義務を負う。\n\n---\n\n**選択肢3**\n\n代理人が自分や第三者の利益のために権限内で行為し、その目的を相手方が知っていた、または知ることができたときは、無権代理行為（代理権のない人がした行為）とみなされる。\n\n---\n\n**選択肢4**\n\n未成年者が法律行為をするときは原則として法定代理人の同意が必要だが、単に権利を得るか義務を免れるだけなら同意は不要である。\n\n(正解 1)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| **1** | 発信時に成立するという旧民法のルール。現在は原則として承諾が**到達した時**に成立する。 |\n| 2 | 民法121条の2に規定されている。 |\n| 3 | 民法107条の代理権濫用の規定。RPGで勉強したところ！ |\n| 4 | 民法5条1項。未成年者についての原則と例外。 |\n\nここは**2020年施行の民法改正**で変わった知識。2026年にも到達主義が基本だよ。\n\n---",
