          "easyMarkdown": "**問題：正しい組合せはどれか。**\n\n買った建物に契約不適合（契約で約束した品質などを満たしていない状態）が見つかった。\n\nただし、売主にも買主にも帰責事由（その人の責任といえる原因）がないものとする。ほかに請求を妨げる事情はない。\n\n買主の4つの権利のうち、**行使できない権利だけを挙げた選択肢**を選ぶ問題だ。\n\n| 権利 | 意味 |\n|--------|--------|\n| 追完請求 | 修理や交換などを求める |\n| 代金減額請求 | 代金を安くしてもらう |\n| 損害賠償請求 | 損害をお金で補ってもらう |\n| 契約解除 | 契約を解消する |\n\n**選択肢1**　行使できないのは「追完請求・損害賠償請求・解除」。\n\n---\n\n**選択肢2**　行使できないのは「代金減額請求・損害賠償請求・解除」。\n\n---\n\n**選択肢3**　行使できないのは「追完請求・代金減額請求」。\n\n---\n\n**選択肢4**　行使できないのは「損害賠償請求」だけ。\n\n(正解 4)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 追完請求と解除までできないとするのが誤り。 |\n| 2 | 代金減額請求と解除までできないとするのが誤り。 |\n| 3 | 追完請求・減額請求は、売主に帰責事由がなくてもできる。 |\n| **4** | 損害賠償には原則として売主の帰責事由が必要。双方に帰責事由がない今回は請求できない。 |\n\n**暗記：「追完・減額・解除は帰責事由がなくても可能。賠償は売主の帰責事由が必要！」**\n\n※追完・減額・解除にはそれぞれ別の要件がある。本問では、それらの要件は満たしている前提。",
