          "easyMarkdown": "**問題：Aが自宅の増築をBに請け負わせ、3か月で工事が完了した。増築部分は元の建物と一体となる。誤っているものはどれか。**\n\n1. Aが工事代金をまだ支払っていなくても、増築部分は原則としてAの所有になる。\n2. Bの材料を使った増築部分に契約不適合（契約で約束した品質に合わない欠陥）があった場合、Aは**工事完了日から1年以内**に通知しなければ修補（修理）を求められない。\n3. Bが欠陥を知りながら黙っており、Aが工事完了から3年後に知った場合、消滅時効が完成していなければ修補請求が認められる場合がある。\n4. Aが提供した材料そのものの問題で欠陥が生じ、Bが材料の不適当を知らなかった場合、原則としてAはBに修補を請求できない。\n\n(正解 2（誤り）)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 一体化した増築部分は元の建物に付合（付いて一体となること）する。 |\n| **2** | 通知期限は原則**不適合を知った時から1年**。完了日からではない。 |\n| 3 | Bが悪意なら1年の通知期間制限の例外となる。 |\n| 4 | 注文者Aが提供した材料の性質が原因なら、原則Bに責任を問えない。 |\n\n**覚え方：「請負の不適合は、原則『知ってから1年』で通知！」**",
