          "easyMarkdown": "(2026年用語変更)\n\n**問題：宅建業者の免許取消しについて、正しいものはどれか。**\n\n1. 宅建業を行う支店の代表者（政令で定める使用人）が道路交通法違反で懲役刑に処せられても、会社の免許が取り消されることはない。\n2. 会社の取締役が所得税法違反で罰金刑に処せられても、そのことだけでは会社の免許は取り消されない。\n3. 個人の宅建業者が宅建業法違反で罰金刑に処せられても、業者免許は取り消されない。\n4. 非常勤取締役が脅迫罪（他人を脅す犯罪）で罰金刑に処せられても、会社の免許は取り消されない。\n\n(正解 2)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 支店代表者が欠格事由に該当する。罪名にかかわらず拘禁刑以上の刑なら原則取消しの対象。 |\n| **2** | 所得税法違反による罰金刑だけでは、列挙された欠格事由に当たらない。 |\n| 3 | 宅建業法違反による罰金刑は欠格事由。 |\n| 4 | 非常勤でも役員。脅迫罪による罰金刑は欠格事由。 |\n\n**2026年向け：** 旧「懲役・禁錮」は、2025年6月の刑法改正で**拘禁刑（こうきんけい）**に一本化されている。2026年の試験では「拘禁刑以上」を覚えよう。",
